const puppeteer = require('puppeteer-core');
const path = require('path');

const FILE = 'file://' + path.resolve(process.argv[2] || '/home/dp/MyProjects/disc/.tmpwork/disc-pi-qqpnu5fb/run/index.html');

async function dragItem(page, ulIndex, fromIdx, toIdx) {
  // получить координаты элементов li внутри указанного списка
  const rects = await page.evaluate((ulIndex) => {
    const ul = document.querySelectorAll('.disc-list')[ulIndex];
    const lis = Array.from(ul.querySelectorAll('.disc-item'));
    return lis.map((li) => {
      const r = li.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    });
  }, ulIndex);

  const from = rects[fromIdx];
  const to = rects[toIdx];

  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  // плавное перемещение для срабатывания pointermove
  const steps = 12;
  for (let i = 1; i <= steps; i++) {
    await page.mouse.move(
      from.x + ((to.x - from.x) * i) / steps,
      from.y + ((to.y - from.y) * i) / steps
    );
    await new Promise((r) => setTimeout(r, 16));
  }
  await page.mouse.up();
  await new Promise((r) => setTimeout(r, 60));
}

