// Точный драг: каждый шаг пересчитываем rect целевого слота.
const puppeteer = require('puppeteer-core');
const path = require('path');
const FILE = 'file://' + path.resolve(process.argv[2] || '/home/dp/MyProjects/disc/.tmpwork/disc-pi-qqpnu5fb/run/index.html');

async function dragToSlot(page, ulIndex, fromIdx, toSlot) {
  // старт: центр исходного элемента
  let pos = await page.evaluate((ulIndex, fromIdx) => {
    const ul = document.querySelectorAll('.disc-list')[ulIndex];
    const li = ul.querySelectorAll('.disc-item')[fromIdx];
    const r = li.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  }, ulIndex, fromIdx);

  await page.mouse.move(pos.x, pos.y);
  await page.mouse.down();

  for (let i = 0; i < 60; i++) {
    // текущий центр целевого слота
    const target = await page.evaluate((ulIndex, toSlot) => {
      const ul = document.querySelectorAll('.disc-list')[ulIndex];
      const lis = ul.querySelectorAll('.disc-item');
      const li = lis[Math.min(toSlot, lis.length - 1)];
      const r = li.getBoundingClientRect();
      // для верхней позиции ведём к верхней трети, для нижней — к нижней
      return { x: r.left + r.width / 2, y: r.top + (toSlot === 0 ? r.height * 0.2 : r.height * 0.8) };
    }, ulIndex, toSlot);
    const nx = pos.x + (target.x - pos.x) * 0.25;
    const ny = pos.y + (target.y - pos.y) * 0.25;
    await page.mouse.move(nx, ny, { steps: 2 });
    pos = { x: nx, y: ny };
    await new Promise((r) => setTimeout(r, 12));
  }
  await page.mouse.up();
  await new Promise((r) => setTimeout(r, 80));
}

async function handleDragToSlot(page, ulIndex, fromIdx, toSlot) {
  let pos = await page.evaluate((ulIndex, fromIdx) => {
    const ul = document.querySelectorAll('.disc-list')[ulIndex];
    const li = ul.querySelectorAll('.disc-item')[fromIdx];
    const h = li.querySelector('.disc-handle');
    const r = h.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  }, ulIndex, fromIdx);
  await page.mouse.move(pos.x, pos.y);
  await page.mouse.down();
  for (let i = 0; i < 60; i++) {
    const target = await page.evaluate((ulIndex, toSlot) => {
      const ul = document.querySelectorAll('.disc-list')[ulIndex];
      const li = ul.querySelectorAll('.disc-item')[toSlot];
      const h = li.querySelector('.disc-handle');
      const r = h.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + (toSlot === 0 ? r.height * 0.2 : r.height * 0.8) };
    }, ulIndex, toSlot);
    const nx = pos.x + (target.x - pos.x) * 0.25;
    const ny = pos.y + (target.y - pos.y) * 0.25;
    await page.mouse.move(nx, ny, { steps: 2 });
    pos = { x: nx, y: ny };
    await new Promise((r) => setTimeout(r, 12));
  }
  await page.mouse.up();
  await new Promise((r) => setTimeout(r, 80));
}

async function main() {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome', headless: 'new',
    args: ['--no-sandbox', '--disable-gpu'],
  });

  // ===== десктоп =====
  {
    const page = await browser.newPage();
    await page.setViewport({ width: 1440, height: 900 });
    const errors = [];
    page.on('pageerror', (e) => errors.push(e.message));
    page.on('request', (r) => { if (!r.url().startsWith('file://') && !r.url().startsWith('data:')) errors.push('EXTERNAL: ' + r.url()); });
    await page.goto(FILE, { waitUntil: 'load' });
    await page.click('.hero .btn--accent');
    await new Promise((r) => setTimeout(r, 300));

    const before = await page.evaluate(() => Array.from(document.querySelectorAll('.disc-list')[0].querySelectorAll('.disc-item')).map((l) => l.dataset.type).join(''));
    await dragToSlot(page, 0, 0, 3);
    const after = await page.evaluate(() => Array.from(document.querySelectorAll('.disc-list')[0].querySelectorAll('.disc-item')).map((l) => l.dataset.type).join(''));
    console.log('DESKTOP drag first->last :', before, '=>', after, '(ожидаем cds i)', after === 'cdsi' ? 'PASS' : 'FAIL');

    await dragToSlot(page, 0, 3, 0);
    const back = await page.evaluate(() => Array.from(document.querySelectorAll('.disc-list')[0].querySelectorAll('.disc-item')).map((l) => l.dataset.type).join(''));
    console.log('DESKTOP drag last->first :', back, back === before ? 'PASS' : 'FAIL');

    // вкладка назад/вперёд по табам
    await page.evaluate(() => document.querySelectorAll('.disc-tab')[4].click());
    const pane5 = await page.evaluate(() => !document.querySelector('.disc-pane[data-step-pane="4"]').hidden);
    console.log('TAB NAV to step5:', pane5 ? 'PASS' : 'FAIL');
    console.log('DESKTOP ERRORS:', errors.length ? errors : 'none');
    await page.close();
  }

  // ===== планшет (coarse pointer): drag за ручку =====
  {
    const page = await browser.newPage();
    await page.setViewport({ width: 820, height: 1180, hasTouch: true });
    const errors = [];
    page.on('pageerror', (e) => errors.push(e.message));
    await page.goto(FILE, { waitUntil: 'load' });
    await page.tap('.hero .btn--accent');
    await new Promise((r) => setTimeout(r, 300));

    const byHandleFlag = await page.evaluate(() => matchMedia('(pointer: coarse)').matches);
    console.log('TABLET coarse pointer:', byHandleFlag);

    const before = await page.evaluate(() => Array.from(document.querySelectorAll('.disc-list')[0].querySelectorAll('.disc-item')).map((l) => l.dataset.type).join(''));
    await handleDragToSlot(page, 0, 3, 0);
    const after = await page.evaluate(() => Array.from(document.querySelectorAll('.disc-list')[0].querySelectorAll('.disc-item')).map((l) => l.dataset.type).join(''));
    console.log('TABLET handle drag last->first:', before, '=>', after, after === after[0] + before.replace(after[0], '') ? 'PASS(check)' : 'FAIL');
    console.log('TABLET ERRORS:', errors.length ? errors : 'none');
    await page.close();
  }

  await browser.close();
}
main().catch((e) => { console.error('FATAL', e); process.exit(2); });
