  const p = await b.newPage();
  await p.goto('file://' + path.resolve('/home/dp/MyProjects/disc/.tmpwork/disc-pi-qqpnu5fb/run/index.html'), { waitUntil: 'load' });
  await p.click('.hero .btn--accent');
  await new Promise(r => setTimeout(r, 200));
  await p.focus('.disc-list .disc-item');
  const before = await p.evaluate(() => Array.from(document.querySelectorAll('.disc-list')[0].children).map(l => l.dataset.type).join(''));
  await p.keyboard.down('Alt'); await p.keyboard.press('ArrowDown'); await p.keyboard.up('Alt');
  const after = await p.evaluate(() => Array.from(document.querySelectorAll('.disc-list')[0].children).map(l => l.dataset.type).join(''));
  console.log('KBD alt+down:', before, '=>', after, after === before[1] + before[0] + before.slice(2) ? 'PASS' : 'FAIL');
  // Esc закрывает
  await p.keyboard.press('Escape');
  console.log('ESC closes:', await p.evaluate(() => !document.getElementById('wizardmodal').classList.contains('is-open')) ? 'PASS' : 'FAIL');
  await b.close();
})();
